?>
<div class="container support-breadcrumb"><a href="<?= e(url('/')) ?>">Home</a><span aria-hidden="true">/</span><span><?= e($title) ?></span></div>
<?php if ($type === 'contact' || $type === 'partners-apply'): ?>
