        <div><label for="planner-theme">What draws you here?</label><select name="theme" id="planner-theme"><option value="">All interests</option><?php foreach (($page['filter_options']['theme'] ?? []) as $value => $label): ?><option value="<?= e((string) $value) ?>"<?= ($filters['theme'] ?? '') === (string) $value ? ' selected' : '' ?>><?= e((string) $label) ?></option><?php endforeach; ?></select></div>
