<?php else: $about = $type === 'about' || $type === 'why'; ?>
<section class="container support-space editorial-support"><div class="editorial-support__intro"><?php heading($about ? 'An island perspective' : 'The places between the places', $type === 'about' ? 'Sri Lanka,\nmade personal.' : ($type === 'why' ? 'Your journey.\nYour own perspective.' : $title), $about ? 'Private chauffeur-guided travel, connected places and a Sri Lanka itinerary shaped around individual interests.' : 'A considered space for the existing service information, practical details and planning links.'); ?><a class="button button--dark" href="<?= e(url('/contact')) ?>">Bring your ideas <?= icon('arrow-up-right') ?></a></div><div class="editorial-support__image"><?php image('assets/images/galle-lighthouse.w1200.webp', 'Galle lighthouse framed by palms on the Sri Lankan coast', '', '(max-width: 800px) 90vw, 48vw', true); ?></div></section>
<section class="container support-space support-story"><div><p class="eyebrow"><?= $about ? 'Travel at a human pace' : 'Practical, clear and connected' ?></p><h2><?= e($about ? "More than the places.\nThe way you experience them." : "The details belong\nwith the journey.") ?></h2></div><div><p><?= $about ? 'Island Culture Travels focuses on private chauffeur-guided travel and personalised Sri Lanka trip planning. The new design brings destinations, suggested itineraries and experiences together without turning every journey into a fixed package.' : 'Exact routes, vehicle information, inclusions, exclusions, pricing and service terms must come from the existing approved content. No new transfer price, pickup promise or service guarantee has been invented for this layout.' ?></p><?php if (!empty($page['record']['body']) && !$fixture): foreach ($page['record']['body'] as $section): ?><h3><?= e((string) ($section['heading'] ?? '')) ?></h3><p><?= e((string) ($section['text'] ?? '')) ?></p><?php endforeach; elseif (!$about): ?><p class="field-help">Service-specific content is unavailable in this preview. The original site has not been changed.</p><?php endif; ?></div></section>
<section class="container support-pillars"><article><?= icon('route') ?><h2>Connect the places.</h2><p>Browse destinations alongside relevant journeys and experiences, rather than isolated pages.</p></article><article><?= icon('account') ?><h2>Make it personal.</h2><p>Keep your interests central to the planning conversation, with no implied booking from a simple inquiry.</p></article><article><?= icon('leaf') ?><h2>Leave room to explore.</h2><p>Use suggested journeys for inspiration, not as a substitute for the details of an agreed itinerary.</p></article></section>
